.br-liee>a::after{content:"\00a0→";color:var(--wp--preset--color--accent)}
.br-liee:hover,.br-liee:focus-within{box-shadow:0 0 0 2px var(--wp--preset--color--accent)}
.br-liee>a:focus-visible{outline:none}
.br-liee p{margin:.5rem 0 0;font-size:.95rem}

/* Logo image */
.br-header .wp-block-site-logo{margin:0;line-height:0;flex-shrink:0}
.br-header .wp-block-site-logo img{width:auto!important;height:auto;max-height:52px;max-width:220px}
.br-logo-clair img{display:block;width:auto;height:auto;max-height:52px;max-width:220px}
@media (max-width:781px){.br-header .wp-block-site-logo img{max-height:40px;max-width:170px}}

/* Bande d'appel à l'action compacte : texte à gauche, bouton à droite */
.br-section.br-cta{padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)}
.br-cta-inner{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:var(--wp--preset--spacing--60);align-items:center}
.br-cta-inner>*{grid-column:1;margin-top:0;margin-bottom:0}
.br-cta-inner>h2{margin-bottom:.5rem}
.br-cta-inner>.wp-block-buttons{grid-column:2;grid-row:1 / span 2;margin:0}
