@media (max-width:781px){
.br-section.br-cta{padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50)}
.br-cta-inner{grid-template-columns:1fr}
.br-cta-inner>.wp-block-buttons{grid-column:1;grid-row:auto;margin-top:var(--wp--preset--spacing--40)}
.br-cta::before{width:140px;height:100px;right:-60px;top:-50px}
}
/* Pas deux appels à l'action à la suite : le lien du pied de page s'efface si la page a déjà sa bande */
body:has(main .br-cta) .br-footer-mail{display:none}
.br-cta::after{display:none}

