.br-tete-media{margin:0!important}.br-tete-media img{width:100%;height:100%;object-fit:cover;border-radius:var(--wp--custom--rayon--grand);display:block}
.br-tete .wp-block-columns:not(:has(img,.br-photo-secours))>.wp-block-column:last-child{display:none}
