/* Étapes : frise (accueil) et fil vertical (pages de service), remplis au défilement par motion.js */
.br-fil{--br-rond:3.5rem;position:relative;margin-top:var(--wp--preset--spacing--50)!important}
.br-fil>.br-fil-etape{position:relative;margin:0!important}
.br-fil-num{display:flex;align-items:center;justify-content:center;width:var(--br-rond);height:var(--br-rond);box-sizing:border-box;margin:0!important;border-radius:50%;border:2px solid var(--wp--preset--color--accent);background:var(--wp--preset--color--accent);color:var(--wp--preset--color--fond);font-family:var(--wp--preset--font-family--titres);font-weight:700;font-size:1.3rem;line-height:1;z-index:1;transition:background-color .3s ease,color .3s ease}
.br-fil-etape h3{margin:0!important;font-size:clamp(1.3rem,1.1rem + .5vw,1.6rem);line-height:1.25}
.br-fil-texte{margin:0!important;color:var(--wp--preset--color--texte-doux)}
.br-duree{display:inline-flex;align-items:center;gap:.45rem;width:fit-content;margin:.25rem 0 0!important;padding:.3rem .85rem;border-radius:999px;background:color-mix(in srgb,var(--wp--preset--color--texte) 7%,transparent);font-size:.85rem;font-weight:600;line-height:1.4;color:var(--wp--preset--color--texte)}
.br-duree::before{content:"";flex:none;width:.4rem;height:.4rem;border-radius:50%;background:var(--wp--preset--color--accent)}
.br-fil-etape:not(:last-child)::before,.br-fil-etape:not(:last-child)::after{content:"";position:absolute;z-index:0;border-radius:3px;background:var(--wp--preset--color--accent)}
.br-fil-etape:not(:last-child)::before{opacity:.2}
@media (min-width:782px){
.br-fil--frise{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:2.5rem}
.br-fil--frise .br-fil-etape{display:flex;flex-direction:column;gap:.6rem}
.br-fil--frise .br-fil-num{position:relative;margin-bottom:.6rem!important}
.br-fil--frise .br-fil-etape:not(:last-child)::before,.br-fil--frise .br-fil-etape:not(:last-child)::after{left:calc(var(--br-rond)/2);top:calc(var(--br-rond)/2 - 1.5px);height:3px;width:calc(100% + 2.5rem);transform-origin:left}
.br-fil--frise .br-fil-etape:not(:last-child)::after{transform:scaleX(var(--br-f,1))}
}
.br-fil--vertical .br-fil-etape{display:flex;flex-direction:column;gap:.5rem;padding:0 0 2.25rem calc(var(--br-rond) + 1.25rem)}
.br-fil--vertical .br-fil-etape:last-child{padding-bottom:0}
