.br-etape-media figure{margin:0!important}
.br-etape-media img{width:100%;border-radius:0!important}
.br-etape-media::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,color-mix(in srgb,var(--wp--preset--color--sombre) 72%,transparent));pointer-events:none}
