.br-etape-numero{position:absolute;left:1.2rem;bottom:.35rem;z-index:1;margin:0!important;font-family:var(--wp--preset--font-family--titres);font-weight:600;font-size:clamp(4rem,6vw,6rem);line-height:1;letter-spacing:-.05em;color:#fff}
