.br-cta-photo{padding:var(--wp--preset--spacing--80) var(--wp--style--root--padding-right,1.5rem) var(--wp--preset--spacing--70) var(--wp--style--root--padding-left,1.5rem)!important;min-height:0!important}
.br-cta-photo .wp-block-cover__background{background:linear-gradient(90deg,color-mix(in srgb,var(--wp--preset--color--sombre) 94%,transparent) 0%,color-mix(in srgb,var(--wp--preset--color--sombre) 85%,transparent) 50%,color-mix(in srgb,var(--wp--preset--color--sombre) 42%,transparent) 100%)!important;opacity:1!important}
