.br-cta-photo .br-lead{opacity:.92;max-width:32em}
.br-cta-photo-cols{gap:var(--wp--preset--spacing--60)}
.br-cta-photo .br-appel-bouton{border-color:var(--wp--preset--color--clair);color:var(--wp--preset--color--clair)}
