.br-note-detail{display:flex;flex-direction:column;gap:.2rem;font-size:.95rem;color:var(--wp--preset--color--texte-doux)}
.br-etoiles{color:var(--wp--preset--color--accent);letter-spacing:.12em;font-size:1.15rem;line-height:1}
