.br-avis-court>*{margin:0!important}
.br-avis-court .wp-block-quote{border:0;margin:0;padding:0;display:flex;flex-direction:column;flex:1}
.br-avis-court .wp-block-quote p{font-family:var(--wp--preset--font-family--titres);font-weight:500;font-size:1.35rem;line-height:1.3;letter-spacing:-.015em;margin:0}
.br-avis-court .wp-block-quote cite{margin-top:auto;padding-top:1.25rem;font-style:normal;font-size:.9rem;line-height:1.5;color:var(--wp--preset--color--texte-doux)}
.br-avis-court .wp-block-quote cite strong{color:var(--wp--preset--color--texte)}
