.br-telephone{width:290px;height:590px;margin:0 auto!important;border:12px solid var(--wp--preset--color--sombre);border-radius:44px;background:var(--wp--preset--color--fond);padding:40px 14px 14px;display:flex;flex-direction:column;gap:.35rem;box-shadow:0 40px 80px -40px rgba(0,0,0,.55)}
.br-telephone>*{margin:0!important}
