.br-telephone .br-telephone-photos img{width:100%!important;height:100%!important;object-fit:cover;border-radius:6px}
.br-telephone-bouton{margin-top:auto!important;text-align:center;background:var(--wp--preset--color--accent);color:var(--wp--preset--color--clair);border-radius:999px;font-size:.78rem;font-weight:600;padding:.6rem}
