.br-temps-c2{background:var(--wp--preset--color--secondaire)}
.br-temps-c3{background:var(--wp--preset--color--deco)}
.br-temps-c4{background:var(--wp--preset--color--texte)}
.br-temps-c5{background:var(--wp--preset--color--texte-doux)}
.br-temps-c6{background:var(--wp--preset--color--surface)}
.br-temps tfoot td{font-family:var(--wp--preset--font-family--titres);font-weight:600;font-size:1.3rem;border:0!important;padding-top:1rem}
