.br-cadeau-carte{aspect-ratio:1.6;min-height:0!important;max-width:440px;margin:2rem auto!important;padding:1.5rem 1.6rem!important;border-radius:22px;transform:rotate(-3deg);box-shadow:0 40px 80px -40px rgba(0,0,0,.6)}
