.br-tarif-nom a{color:inherit;text-decoration:none}.br-tarif-nom a::after{content:"";position:absolute;inset:0}.br-tarif-nom a:focus-visible{outline:none}
.br-tarif-ligne:is(:hover,:focus-within) .br-tarif-nom{color:var(--wp--preset--color--accent)}
.br-tarif-ligne:has(a:focus-visible){outline:3px solid var(--wp--preset--color--accent);outline-offset:2px;border-radius:8px}
.br-tarif-details{color:var(--wp--preset--color--texte-doux);font-size:.96rem}
