.br-ensuite{list-style:none;counter-reset:br-e;padding:0;margin:0}
.br-ensuite li{counter-increment:br-e;position:relative;padding:1rem 0 1rem 3.75rem;border-top:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 14%,transparent);color:var(--wp--preset--color--texte-doux);line-height:1.5}
.br-ensuite li::before{content:counter(br-e);position:absolute;left:0;top:1rem;width:44px;height:44px;border-radius:50%;background:var(--wp--preset--color--accent);color:var(--wp--preset--color--clair);display:flex;align-items:center;justify-content:center;font-family:var(--wp--preset--font-family--titres);font-weight:600}
.br-ensuite li strong{display:block;font-family:var(--wp--preset--font-family--titres);font-weight:600;font-size:1.2rem;letter-spacing:-.02em;color:var(--wp--preset--color--texte)}
