.br-formulaire .ff-el-form-check input{accent-color:var(--wp--preset--color--accent);width:20px;height:20px;margin:0}
.br-tete-seance .br-fil-ariane,.br-tete-seance .br-ariane{margin-bottom:1.5rem!important}
.br-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:2.25rem!important;padding-top:1.5rem;border-top:1px solid color-mix(in srgb,var(--wp--preset--color--texte) 14%,transparent)}
.br-stats>*{margin:0!important}
.br-stat{font-size:.9rem;line-height:1.4;color:var(--wp--preset--color--texte-doux)}
.br-stat strong{display:block;font-family:var(--wp--preset--font-family--titres);font-weight:600;font-size:clamp(1.4rem,2.2vw,1.9rem);letter-spacing:-.025em;line-height:1.1;color:var(--wp--preset--color--texte);margin-bottom:.2rem}
.br-tete-seance-media img{width:100%}
.br-galerie-section .br-tete-deux>div>*{margin:0!important}.br-galerie-section .br-tete-deux .br-arrow{margin-top:1rem!important}
