.br-formules-grille{gap:1.25rem}
.br-formule{position:relative;height:100%;background:var(--wp--preset--color--clair);border-radius:var(--wp--custom--rayon--moyen);padding:2rem;display:flex;flex-direction:column;gap:.75rem}
