.br-formule .br-liste-oui li::before{content:"";position:absolute;left:0;top:.6rem;width:1.05rem;height:1.05rem;background:var(--wp--preset--color--accent);-webkit-mask:var(--br-i-coche) center/contain no-repeat;mask:var(--br-i-coche) center/contain no-repeat}
.br-options td:last-child{text-align:right;white-space:nowrap;font-weight:600}
.br-article-texte{max-width:44rem!important}
