.br-article-texte h2:first-child{margin-top:0!important}
.br-cta-photo a:not(.wp-element-button):not(.br-appel-bouton){color:var(--wp--preset--color--clair);text-decoration-color:var(--wp--preset--color--deco)}
.br-faits-section:not(.has-surface-background-color) .br-fait{background:var(--wp--preset--color--surface)}
