@media (max-width:781px){.br-tete-deux{grid-template-columns:1fr;align-items:start}.br-choix-cols{display:flex!important;flex-direction:column}.br-choix-cols>.wp-block-column:first-child{display:contents}.br-choix-cols>.wp-block-column:first-child>*{order:1}.br-choix-cols>.wp-block-column:last-child{order:2;width:100%;max-width:none!important;flex-basis:auto!important;align-self:stretch;margin:0!important}.br-choix-cols>.wp-block-column:first-child>.br-choix-liste{order:3;margin-top:1.75rem!important}.br-choix-scene{min-height:0;height:auto;aspect-ratio:4/5}.br-choix-scene>.br-choix-photo:not(:first-child){display:none}.br-choix .br-dispo-carte{left:.9rem;right:.9rem;top:.9rem;bottom:auto;padding:.8rem 1rem;border-radius:16px}.br-choix-ligne{grid-template-columns:64px 1fr auto;align-items:center;padding:.6rem 0!important}.br-choix-vignette{display:block;width:64px}.br-choix-vignette img{border-radius:14px;width:64px;height:64px;object-fit:cover}.br-choix-nom{font-size:1.5rem}.br-eventail .br-eventail-photos{grid-template-columns:1fr 1.25fr 1fr;gap:.6rem;margin-left:-2.5rem!important;margin-right:-2.5rem!important;margin-top:2.25rem!important}.br-eventail-photos>figure:nth-child(1),.br-eventail-photos>figure:nth-child(5){display:none}.br-eventail-photos>figure:nth-child(2),.br-eventail-photos>figure:nth-child(4){margin-top:2.5rem!important}.br-faits{grid-template-columns:1fr}.br-lieu-media .br-dispo-carte{left:.9rem;right:.9rem;bottom:.9rem;max-width:none;padding:.8rem 1rem;border-radius:16px}.br-stats{grid-template-columns:1fr 1fr 1fr;gap:.6rem}.br-stat{font-size:.8rem}.br-stat strong{font-size:1.15rem}.br-faits-cote{position:static}.br-faits-cote img{aspect-ratio:3/2!important;object-fit:cover}.br-etapes-images-grille{grid-auto-flow:row;grid-template-columns:1fr 1fr;gap:1.25rem}.br-etape-numero{font-size:3.5rem}.br-cta-photo .wp-block-cover__background{background:linear-gradient(180deg,color-mix(in srgb,var(--wp--preset--color--sombre) 70%,transparent),color-mix(in srgb,var(--wp--preset--color--sombre) 92%,transparent) 45%)!important}.br-tarif-ligne{grid-template-columns:64px 1fr auto;gap:.4rem 1rem}.br-tarif-vignette{grid-row:span 2}.br-tarif-details{grid-column:2/4;grid-row:2;font-size:.9rem}.br-tarif-nom{font-size:1.4rem}.br-tarif-prix{font-size:1.2rem}.br-mosaique-dense{grid-template-columns:1fr 1fr!important}.br-reservation-cote{position:static}.br-telephone{transform:scale(.86);transform-origin:top center;margin-bottom:-80px!important}.br-hero-photo .wp-block-column:last-child{max-width:none;margin:0}.br-hero-photo .br-hero-img img{aspect-ratio:4/3!important}}
@media (prefers-reduced-motion:reduce){.br-choix-ligne,.br-choix-scene>.br-choix-photo{transition:none}}
